Object.assign(copy.en,{"skipContent": "Skip to content", "phoneLabel": "Phone with country code (optional)", "privacyTitle": "Privacy", "termsTitle": "Terms and refunds", "cookiesTitle": "Cookies and storage", "privacySettings": "Privacy settings", "dataMinimisation": "Provide only the adult enquirer’s details. Do not send children’s names, identity documents, health information or payment details.", "privacyConsent": "I agree to the processing of these details to respond to my enquiry.", "errorConsent": "Please agree to processing your details so we can reply.", "mapConsentCopy": "Loading the map shares connection details with Google. You can open directions separately or allow the map here.", "enableMap": "Load Google Maps", "cookieNotice": "No analytics or advertising. This site stores your language and privacy choices in your browser. Google Maps loads only with your permission.", "essentialOnly": "Continue without Google Maps", "allowMap": "Allow Google Maps", "details": "Details", "close": "Close", "privacyReset": "Delete preferences and disable map", "resetDone": "Saved preferences deleted and map disabled. This does not delete emails already sent.", "contactTitle": "Enquire about availability", "confirmPersonally": "Email your dates and group size. Payment, cancellation and refund terms will be agreed by email before payment; the hotel voucher confirms the stay.", "formPending": "The online form is not available yet. Please use the email in Contacts.", "contactLabel": "Contacts", "privacySummary": "An enquiry does not confirm a booking. No payment is taken on this site."});
Object.assign(copy.es,{"skipContent": "Ir al contenido", "phoneLabel": "Teléfono con prefijo (opcional)", "privacyTitle": "Privacidad", "termsTitle": "Condiciones y reembolsos", "cookiesTitle": "Cookies y almacenamiento", "privacySettings": "Preferencias de privacidad", "dataMinimisation": "Indica solo los datos de la persona adulta que hace la consulta. No envíes nombres de menores, documentos, información médica ni datos de pago.", "privacyConsent": "Acepto el tratamiento de estos datos para recibir una respuesta a mi consulta.", "errorConsent": "Acepta el tratamiento de tus datos para que podamos responder.", "mapConsentCopy": "Al cargar el mapa, Google recibe datos de conexión. Puedes abrir la ruta por separado o permitir el mapa aquí.", "enableMap": "Cargar Google Maps", "cookieNotice": "Sin analítica ni publicidad. El sitio guarda el idioma y las preferencias en tu navegador. Google Maps solo se carga con tu permiso.", "essentialOnly": "Continuar sin Google Maps", "allowMap": "Permitir Google Maps", "details": "Más información", "close": "Cerrar", "privacyReset": "Borrar preferencias y desactivar mapa", "resetDone": "Preferencias borradas y mapa desactivado. Esto no elimina correos ya enviados.", "contactTitle": "Consultar disponibilidad", "confirmPersonally": "Escríbenos con las fechas y el número de huéspedes. Las condiciones de pago, cancelación y reembolso se acordarán por email antes del pago; el hotel confirmará la estancia en el bono.", "formPending": "El formulario online aún no está disponible. Utiliza el email de Contacto.", "contactLabel": "Contacto", "privacySummary": "La consulta no confirma una reserva. No se realizan pagos en este sitio."});
const legalContent={"ru": {"privacy": [["Что обрабатывает сайт", "Для показа страниц сервер хостинга получает технические данные подключения, включая IP-адрес. В браузере сохраняются только язык и выбор приватности. Аналитики, рекламных пикселей и рассылки нет."], ["Запросы и переписка", "Онлайн-форма сейчас не подключена и данные не отправляет. При обращении по email письмо обрабатывается почтовым сервисом и получателем для ответа и обсуждения проживания. Телефон необязателен; количество детей — только числом. Не отправляйте персональные данные детей."], ["Карта и внешние сервисы", "Google Maps отключена до вашего согласия. После её загрузки Google получает данные подключения и может использовать cookies по своей политике. Ссылки на маршрут открывают внешний сайт Google."], ["Удаление и вопросы", "Для запроса доступа, исправления или удаления данных обратитесь по email в разделе «Контакты». Укажите, какое обращение нужно найти; не прикладывайте документы без необходимости. Срок хранения переписки и полные реквизиты оператора ещё не определены для публикации. Эта информация требует дополнения владельцем до подключения приёма заявок."]], "cookies": [["Что хранится в браузере", "Сам сайт не устанавливает cookies. В localStorage сохраняются indah-language (язык) и indah-privacy-v1 (выбор о карте). Они остаются до удаления через настройки сайта или браузера. При запрете хранения настройки действуют только в текущем открытии страницы."], ["Необязательная карта", "Google-карта загружается только после разрешения. Кнопки отказа и разрешения доступны без регистрации. Отказ не мешает пользоваться сайтом. Отозвать разрешение и удалить локальные настройки можно ниже. Ранее установленные Google cookies удаляются в настройках браузера."], ["Сторонние правила", "GitHub Pages обрабатывает технические запросы при размещении сайта. Для Google после разрешения действуют его собственные условия и политика приватности."]], "terms": [["Запрос доступности", "Сайт знакомит с виллой и помогает связаться с владельцем. Отправка запроса или письма сама по себе не подтверждает бронирование. Онлайн-оплаты и мгновенного бронирования здесь нет."], ["Оплата, отмена и возврат", "Итоговая стоимость, состав услуг, предоплата, сроки отмены и условия возврата направляются по email и согласуются до оплаты. Подтверждение проживания оформляется ваучером отеля. Если условия не получены или непонятны, запросите их до оплаты. Сайт не обещает бесплатную отмену или возврат."], ["Дополнительные расходы", "Рестораны, напитки, аренда лежаков, спа и другие дополнительные услуги могут оплачиваться отдельно. Состав включённых услуг и все обязательные сборы нужно подтвердить в письменном предложении до оплаты."], ["Кто заключает договор", "Полные данные стороны договора и её реквизиты должны быть указаны в предложении и документах бронирования. Адрес виллы указан внизу сайта; это адрес объекта проживания, а не подтверждённый юридический адрес оператора. Публичная оферта с полными реквизитами и согласованными условиями пока не опубликована."]]}, "en": {"privacy": [["Site data", "The hosting server receives technical connection information, including an IP address, to deliver pages. Only language and privacy choices are stored in your browser. There are no analytics, advertising pixels or newsletters."], ["Enquiries", "The online form is not connected and sends no data. Email enquiries are processed by the email provider and recipient to reply and discuss a stay. Phone is optional; only a number of children is requested. Do not send children’s personal details."], ["Maps and external services", "Google Maps stays off until you allow it. Loading it shares connection data with Google, which may use cookies under its policies. Directions links open Google’s external site."], ["Access and deletion", "Use the email in Contacts to request access, correction or deletion. Identify the enquiry without attaching unnecessary documents. The correspondence retention period and full operator details are still awaiting confirmation for publication. The owner must complete these before enabling online enquiry collection."]], "cookies": [["Browser storage", "The site itself sets no cookies. localStorage contains indah-language (language) and indah-privacy-v1 (map choice). These remain until removed in site settings or your browser. If storage is blocked, choices last for the current page only."], ["Optional map", "Google Maps loads only after permission. Both allow and decline choices are available without registration. Declining does not prevent use of the site. Revoke permission and delete local preferences below. Previously set Google cookies can be removed in your browser settings."], ["Third parties", "GitHub Pages processes technical requests to host the site. Google’s own terms and privacy policy apply after you allow the map."]], "terms": [["Availability enquiries", "This site presents the villa and provides a way to contact its owner. An enquiry or email alone does not confirm a booking. There are no online payments or instant bookings here."], ["Payment, cancellation and refunds", "The total price, included services, deposit, cancellation deadlines and refund terms are sent and agreed by email before payment. The hotel voucher confirms the stay. If terms are missing or unclear, request them before paying. The site does not promise free cancellation or refunds."], ["Extra charges", "Dining, drinks, sun loungers, spa and other additional services may be charged separately. Confirm included services and all mandatory charges in the written offer before payment."], ["Contracting party", "The contracting party’s full identity and details must appear in the offer and booking documents. The address below is the accommodation address, not a verified legal address for the operator. A complete public booking offer has not yet been published."]]}, "es": {"privacy": [["Datos del sitio", "El alojamiento web recibe datos técnicos de conexión, incluida la dirección IP, para servir las páginas. El navegador solo guarda el idioma y las preferencias. No hay analítica, píxeles publicitarios ni boletines."], ["Consultas", "El formulario online no está conectado ni envía datos. El proveedor de email y el destinatario tratan los correos para responder y gestionar la estancia. El teléfono es opcional; de los menores solo se pide la cantidad. No envíes sus datos personales."], ["Mapa y servicios externos", "Google Maps permanece desactivado hasta que lo permitas. Al cargarlo, Google recibe datos de conexión y puede usar cookies según sus políticas. Los enlaces de ruta abren la web externa de Google."], ["Acceso y eliminación", "Usa el email de Contacto para solicitar acceso, rectificación o eliminación de datos. Identifica tu consulta sin adjuntar documentos innecesarios. El plazo de conservación de correos y los datos completos del responsable están pendientes de confirmación. El propietario debe completarlos antes de activar la recogida de consultas online."]], "cookies": [["Almacenamiento", "El propio sitio no instala cookies. localStorage contiene indah-language (idioma) e indah-privacy-v1 (preferencia del mapa). Permanecen hasta que los borres desde el sitio o el navegador. Si el almacenamiento está bloqueado, las preferencias duran solo durante la página actual."], ["Mapa opcional", "Google Maps solo se carga con permiso. Puedes aceptar o rechazar sin registrarte. Rechazar no impide usar el sitio. Puedes retirar el permiso y borrar las preferencias abajo. Las cookies previas de Google se eliminan desde el navegador."], ["Terceros", "GitHub Pages procesa solicitudes técnicas para alojar el sitio. Al permitir el mapa se aplican las condiciones y la política de privacidad de Google."]], "terms": [["Consulta de disponibilidad", "El sitio presenta la villa y permite contactar con el propietario. Una consulta o un email no confirman una reserva. Aquí no se realizan pagos ni reservas instantáneas."], ["Pago, cancelación y reembolso", "El precio total, los servicios incluidos, el anticipo y las condiciones de cancelación y reembolso se envían y acuerdan por email antes del pago. El hotel confirma la estancia en el bono. Si faltan condiciones o no están claras, solicítalas antes de pagar. El sitio no promete cancelación gratuita ni reembolsos."], ["Gastos adicionales", "Los restaurantes, bebidas, tumbonas, spa y otros servicios adicionales pueden cobrarse aparte. Confirma los servicios incluidos y todos los cargos obligatorios en la oferta escrita antes de pagar."], ["Parte contratante", "Los datos completos de la parte contratante deben figurar en la oferta y los documentos de reserva. La dirección al pie es la del alojamiento, no un domicilio legal verificado del responsable. Todavía no se ha publicado una oferta completa de reserva."]]}};

